Add a controlled date field and include its value in the submitted object. The browser handles the date picker; no custom widget drama required.

```jsx
import { useState } from 'react';

export default function SignupForm({ onSubmit }) {
  const [name, setName] = useState('');
  const [date, setDate] = useState('');

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        onSubmit({ name, date });
      }}
    >
      <label>
        Name <input value={name} onChange={(e) => setName(e.target.value)} />
      </label>

      <label>
        Date <input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
      </label>

      <button type="submit">Save</button>
    </form>
  );
}
```

The date is submitted as a `YYYY-MM-DD` string, or `''` if left empty.

